package net.flovex.core;
import net.flovex.core.data.Storage;import net.flovex.core.economy.EconomyHook;import net.flovex.core.market.Marketplace;import net.flovex.core.platform.PlatformService;import net.flovex.core.scoreboard.ScoreboardService;import net.flovex.core.ui.MenuService;import net.flovex.core.command.CoreCommands;import net.flovex.core.social.TeamService;import net.flovex.core.world.WarpService;import net.flovex.core.text.MessageService;import net.flovex.core.text.SoundService;import net.flovex.core.integration.FlovexExpansion;import org.bukkit.Bukkit;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.plugin.java.JavaPlugin;import java.io.File;
public final class FlovexCore extends JavaPlugin{
 private Storage storage;private EconomyHook economy;private Marketplace market;private PlatformService platform;private MenuService menus;private ScoreboardService scoreboard;private TeamService teams;private WarpService warps;private MessageService messages;private SoundService sounds;private YamlConfiguration worth,scoreboardCfg,menusCfg,settingsCfg,auctionCfg,ordersCfg;
 @Override public void onEnable(){saveDefaultConfig();for(String f:new String[]{"database.yml","worth.yml","scoreboard.yml","homes.yml","teleport.yml","menus.yml","sounds.yml","pvp.yml","moderation.yml","teams.yml","warps.yml","rules.yml","messages.yml","settings.yml","auction-house.yml","orders.yml"})saveResource(f,false);try{YamlConfiguration db=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"database.yml"));storage=new Storage(getDataFolder().toPath(),db.getString("storage.file","flovexcore.db"));economy=new EconomyHook();platform=new PlatformService();market=new Marketplace(storage,economy,auctionCfg,ordersCfg);teams=new TeamService(storage);warps=new WarpService(storage);messages=new MessageService(this);sounds=new SoundService(this);menusCfg=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"menus.yml"));settingsCfg=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"settings.yml"));auctionCfg=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"auction-house.yml"));ordersCfg=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"orders.yml"));menus=new MenuService(this,platform);scoreboard=new ScoreboardService(this);worth=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"worth.yml"));scoreboardCfg=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"scoreboard.yml"));CoreCommands commands=new CoreCommands(this);for(String n:getDescription().getCommands().keySet()){var c=getCommand(n);if(c!=null){c.setExecutor(commands);c.setTabCompleter(commands);}}Bukkit.getPluginManager().registerEvents(commands,this);Bukkit.getPluginManager().registerEvents(menus,this);if(Bukkit.getPluginManager().isPluginEnabled("PlaceholderAPI"))new FlovexExpansion(this).register();scoreboard.start();Bukkit.getScheduler().runTaskTimer(this,()->market.cleanup(),1200L,1200L);Bukkit.getScheduler().runTaskTimer(this,()->Bukkit.getOnlinePlayers().forEach(p->{try{storage.update("INSERT INTO player_data(uuid,last_name,first_join,play_ticks,last_seen) VALUES(?,?,?,?,?) ON CONFLICT(uuid) DO UPDATE SET last_name=excluded.last_name,play_ticks=player_data.play_ticks+1200,last_seen=excluded.last_seen",p.getUniqueId().toString(),p.getName(),System.currentTimeMillis(),1200,System.currentTimeMillis());}catch(Exception ignored){}}),1200,1200);getLogger().info("FlovexCore enabled. Vault economy provider: "+economy.provider()+". Geyser: "+platform.geyserAvailable()+", Floodgate: "+platform.floodgateAvailable());}catch(Exception e){getLogger().severe("Failed to initialize FlovexCore: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);}}
 @Override public void onDisable(){if(scoreboard!=null)scoreboard.stop();if(storage!=null)storage.close();}
 public Storage getStorage(){return storage;}public EconomyHook getEconomy(){return economy;}public Marketplace getMarket(){return market;}public PlatformService getPlatform(){return platform;}public MenuService getMenus(){return menus;}public ScoreboardService getScoreboard(){return scoreboard;}public YamlConfiguration worthConfig(){return worth;}public YamlConfiguration scoreboardConfig(){return scoreboardCfg;}public TeamService getTeams(){return teams;}public WarpService getWarps(){return warps;}public MessageService getMessages(){return messages;}public SoundService getSounds(){return sounds;}public YamlConfiguration menusConfig(){return menusCfg;}public YamlConfiguration settingsConfig(){return settingsCfg;}
}